mapper.select:
select mn.*, sd.D_Name as gfpsProjectCompetentDepartmentName, gfpSum.totalFundApplyAmount, gfpSum.totalNextMonthFunds from Group_Fund_Plan_Summary mn left join SYS_Department sd on mn.Gfps_Project_Competent_Department_Id = sd.D_ID left join ( select gfpsd.Gfps_Id, sum(gfp.Gfp_Fund_Apply_Amount) as totalFundApplyAmount, sum(gfp.gfp_next_month_funds_total) as totalNextMonthFunds from Group_Fund_Plan gfp left join Group_Fund_Plan_Summary_Detail gfpsd on gfpsd.Gfp_Id = gfp.Id left join Group_Fund_Plan_Summary gfps on gfpsd.Gfps_Id = gfps.Id where gfp.State = 7 and gfpsd.del_flag = 0 and gfpsd.status = 0 and gfps.del_flag = 0 and gfp.del_flag = 0 group by gfpsd.Gfps_Id ) gfpSum on gfpSum.Gfps_Id = mn.id ${params.authSql} and mn.state !=3 and mn.del_flag = 0
and mn.Gfps_Project_Competent_Department_Id = #{params.gfpsProjectCompetentDepartmentId}
and mn.Gfps_Type = #{params.gfpsType}
and mn.Gfps_Year = #{params.gfpsYear}
and mn.Gfps_Month = #{params.gfpsMonth}
and mn.Group_Id = #{params.groupId}
and mn.Group_Main_Type = #{params.groupMainType}
and mn.Gfps_Title like concat('%',#{params.gfpsTitle},'%')
order by mn.Create_Time desc

select gfp.id as gfpId, pp.P_Name as pname,pp.P_Name as projectName,gfp.Project_ID as projectId,gfp.Gfp_Month as gfpMonth,gfp.Gfp_Year as gfpYear,gfp.Create_Time as createTime, pp.P_Inv_Total as projectInvTotal,pp.P_Approve_Budget_Code as projectApproveBudgetCode, pp.P_Approve_Budget as projectApproveBudget,ibd.bd_approval_num as bdApprovalNum, gfp.Gfp_Project_Progress as gfpProjectProgress, gfp.Gfp_Arrived_Funds as gfpArrivedFunds, gfp.Gfp_Balance_Funds as gfpBalanceFunds, gfp.Gfp_Member_Balance_Funds as gfpMemberBalanceFunds, gfp.Gfp_Fund_Demand_Amount as gfpFundDemandAmount, gfp.Gfp_Fund_Apply_Amount as gfpFundApplyAmount, gfp.Gfp_Arrange_Funds as gfpArrangeFunds, gfp.Gfp_Next_Month_Funds as gfpNextMonthFunds, pp.P_Competent_Department as gfpsProjectCompetentDepartmentId, sd.D_Name as gfpsProjectCompetentDepartmentName,gfp.Project_Total as projectTotal from Group_Fund_Plan gfp left join Pre_Project pp on gfp.Project_ID = pp.P_ID left join Inv_Budget_Declare ibd on pp.P_ID = ibd.P_ID left join SYS_Department sd on pp.P_Competent_Department = sd.D_ID
gfp.state = 7 and gfp.del_flag = 0
and gfp.Gfp_Month = #{params.gfpsMonth}
and gfp.Gfp_Year = #{params.gfpsYear}
and pp.P_Competent_Department in
#{item}
and gfp.id not in ( select gfpsd.Gfp_Id from Group_Fund_Plan_Summary_Detail gfpsd left join Group_Fund_Plan_Summary gfps on gfpsd.Gfps_Id = gfps.Id where gfpsd.status =0 and gfpsd.del_flag =0 and gfps.state !=3 and gfps.gfps_type = 1 and gfps.del_flag = 0 )
and gfp.id not in ( select gfpsd.Gfp_Id from Group_Fund_Plan_Summary_Detail gfpsd left join Group_Fund_Plan_Summary gfps on gfpsd.Gfps_Id = gfps.Id where gfpsd.status =0 and gfpsd.del_flag =0 and gfps.state !=3 and gfps.gfps_type = 2 and gfps.del_flag = 0 ) and gfp.id in ( select gfpsd.Gfp_Id from Group_Fund_Plan_Summary_Detail gfpsd left join Group_Fund_Plan_Summary gfps on gfpsd.Gfps_Id = gfps.Id where gfpsd.status =0 and gfpsd.del_flag =0 and gfps.state =7 and gfps.gfps_type = 1 and gfps.del_flag = 0 ) order by sd.d_Sort

select * from Group_Fund_Plan_Summary gfps where gfps.id in

    #{item}

and gfps.del_flag = 0

select p.D_ID
from Group_Fund_Plan_Summary gfps
left join SYS_User u on gfps.Create_Uid = u.U_ID
left join SYS_Position_User pu on u.U_ID = pu.U_ID
left join SYS_Position p on pu.P_ID = p.P_ID
where gfps.state != 3
and gfps.del_flag = 0
and gfps.Group_Main_Type = 'new'

    and gfps.id != #{id}

and gfps.Gfps_Year = #{year}
and gfps.Gfps_Month = #{month}
and gfps.Gfps_Type = #{type}
